CREATE TABLE ibexa_content_type (id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, status INTEGER DEFAULT 0 NOT NULL, always_available INTEGER DEFAULT 0 NOT NULL, contentobject_name VARCHAR(255) DEFAULT NULL, created INTEGER DEFAULT 0 NOT NULL, creator_id INTEGER DEFAULT 0 NOT NULL, identifier VARCHAR(50) DEFAULT '' NOT NULL, initial_language_id BIGINT DEFAULT 0 NOT NULL, is_container INTEGER DEFAULT 0 NOT NULL, language_mask BIGINT DEFAULT 0 NOT NULL, modified INTEGER DEFAULT 0 NOT NULL, modifier_id INTEGER DEFAULT 0 NOT NULL, remote_id VARCHAR(100) DEFAULT '' NOT NULL, serialized_description_list CLOB DEFAULT NULL, serialized_name_list CLOB DEFAULT NULL, sort_field INTEGER DEFAULT 1 NOT NULL, sort_order INTEGER DEFAULT 1 NOT NULL, url_alias_name VARCHAR(255) DEFAULT NULL);
